"""Regenerate the committed DejaVu Sans advances (Pillow 11.3.0 / FreeType).

Run from the repository root, then npx prettier --write src/layout/font-metrics.ts.
The fixture font and its license are pinned under test/fixtures/fonts/.
"""
from pathlib import Path
from PIL import ImageFont

font = ImageFont.truetype("test/fixtures/fonts/DejaVuSans.ttf", 1000)
# ASCII, Latin-1 printable, Latin Extended-A, Greek/Coptic, Cyrillic, punctuation.
ranges = [(0x20, 0x7E), (0xA0, 0x17F), (0x370, 0x4FF), (0x2000, 0x206F)]
out = [
    "// Generated by scripts/font-metrics.py; DejaVu Sans, 1000 units, no kerning.",
    "// See FONT-LICENSE.txt. Unlisted code points use the one-em fallback.",
    "export const sansRanges: readonly (readonly [number, readonly number[]])[] = [",
]
for start, end in ranges:
    values = [round(font.getlength(chr(cp)), 3) for cp in range(start, end + 1)]
    out.append(f"  [0x{start:x}, [")
    for i in range(0, len(values), 8):
        out.append("    " + ", ".join(str(v) for v in values[i:i + 8]) + ",")
    out.append("  ]],")
out.extend(["];", ""])  # monoAdvance lives in src/layout/mono-metrics.ts
Path("src/layout/font-metrics.ts").write_text("\n".join(out))
